2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "$id": "release-artifact@2",
4	  "title": "ReleaseArtifact",
5	  "description": "What was in a release: version, changesets, and breaking changes. Supersedes release-artifact@1 — the changesets array now consumes changeset@2's consumer_impact/semver_impact directly instead of redeclaring a separate type field.",
6	  "type": "object",
7	  "required": ["version", "date", "changesets"],
8	  "additionalProperties": false,
9	  "properties": {
10	    "version": {
11	      "type": "string",
12	      "description": "Semver version string (e.g. 1.2.0)"
13	    },
14	    "date": {
15	      "type": "string",
16	      "format": "date",
17	      "description": "Release date in ISO 8601 format (YYYY-MM-DD)"
18	    },
19	    "changesets": {
20	      "type": "array",
21	      "minItems": 1,
22	      "description": "changeset@2 entries included in this release. A changeset IS the changelog entry — semver_impact and consumer_impact are set once at authoring time (shared/schemas/changeset@2.json) and consumed here, not re-derived. release-summarizer's version is max(semver_impact) across this array, with consumer_impact: internal-only entries filtered out before this array is built.",
23	      "items": {
24	        "type": "object",
25	        "required": ["summary", "consumer_impact", "semver_impact"],
26	        "additionalProperties": false,
27	        "properties": {
28	          "summary": {
29	            "type": "string",
30	            "description": "One sentence describing what changed, written from the consumer's perspective"
31	          },
32	          "consumer_impact": {
33	            "type": "string",
34	            "enum": ["behavior-change", "new-capability", "internal-only"]
35	          },
36	          "semver_impact": {
37	            "type": "string",
38	            "enum": ["major", "minor", "patch", "none"]
39	          },
40	          "linked_requirement": {
41	            "type": "string",
42	            "description": "ID of the requirement@1 this changeset addresses"
43	          },
44	          "pr_url": {
45	            "type": "string",
46	            "description": "URL of the merged PR"
47	          },
48	          "commits": {
49	            "type": "array",
50	            "items": { "type": "string" },
51	            "description": "Git SHAs included in this changeset"
52	          }
53	        }
54	      }
55	    },
56	    "breaking_changes": {
57	      "type": "array",
58	      "items": { "type": "string" },
59	      "description": "Human-readable descriptions of all breaking changes in this release"
60	    },
61	    "migration_guide": {
62	      "type": "string",
63	      "description": "Optional: instructions for upgrading from the previous version"
64	    },
65	    "reasoning": {
66	      "type": "string",
67	      "description": "Agent scratchpad — not consumed downstream"
68	    }
